// Pass 3B: Bungenas-inspired abandoned Swedish coastal defence architecture.
// The only gameplay-safe place for a non-colliding ruin is OUTSIDE logical floors.
// Pure data planner; actual geometry is generated by military-architecture.mjs.
import {coastlineProfile} from './coastline.mjs?v=2.28.20-bridge1';
import {propReservations} from './props-placement.mjs?v=2.28.20';
import {planCoastalLifeDressing} from './polyfork-coastal-life.mjs?v=coastal-life-v1';
import {seededRandom} from './polyfork-profiles.mjs?v=profile-v1';

export const MILITARY_FORMS=Object.freeze([
  {id:'coastal-pillbox',label:'Partly buried coastal pillbox',width:3.7,depth:1.35,height:1.55},
  {id:'overgrown-foundations',label:'Overgrown concrete zigzag foundations',width:4.5,depth:1.30,height:.82},
  {id:'sealed-rock-portal',label:'Sealed rock-cut bunker entrance',width:3.45,depth:1.35,height:2.05},
]);
const TAU=Math.PI*2;
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const rectNear=(x,z,f,pad=0)=>Math.abs(x-f.x)<=f.w/2+pad&&Math.abs(z-f.z)<=f.d/2+pad;
const floorContains=(floor,x,z,pad=0)=>rectNear(x,z,floor,pad);
function outerRadius(coast,x,z){
  const f=coast.floor,theta=(Math.atan2(z-f.z,x-f.x)+TAU)%TAU;
  const q=theta/TAU*coast.points.length,i=Math.floor(q)%coast.points.length,t=q-Math.floor(q);
  const a=coast.points[i].radial,b=coast.points[(i+1)%coast.points.length].radial;
  return a+(b-a)*t;
}
function safeAnchorage(level,res,coast,center,normal,tangent,width,depth){
  const f=coast.floor;
  // A 0.19 m air gap separates the front facade from the logical island edge.
  // The foundation extends seaward, never across a navigable floor or bridge.
  const samples=[];
  for(const u of [-.48,0,.48])for(const v of [0,.58,1]){
    const x=center.x+normal.x*(v*depth)+tangent.x*(u*width);
    const z=center.z+normal.z*(v*depth)+tangent.z*(u*width);
    samples.push({x,z});
    const d=Math.hypot(x-f.x,z-f.z);
    if(d>outerRadius(coast,x,z)-.045)return false;
    if((level.floors??[]).some(floor=>floorContains(floor,x,z,.055)))return false;
    if(res.blocked(x,z,.14))return false;
    // Shoreline rock colliders form the headland; bury concrete into them rather
    // than rejecting every military wall site. All samples remain off playable floors.
    if((level.boxes??[]).some(b=>rectNear(x,z,b,.12)))return false;
  }
  // Visual footprint touches no gameplay corridor, enemy or interaction space.
  return samples.length===9;
}
export function militarySites(level,excludeIsland=-1){
  if(!level?.archipelago)return [];
  const islands=(level.floors??[]).filter(f=>!f.dir);
  if(islands.length<2)return [];
  const res=propReservations(level),r=seededRandom(level.seed+':bungenas-fortification-v2');
  const candidates=[];
  const maxW=Math.max(...MILITARY_FORMS.map(f=>f.width));
  const maxD=Math.max(...MILITARY_FORMS.map(f=>f.depth));
  for(const [islandIndex,f] of islands.entries()){
    if(Math.min(f.w,f.d)<9.5)continue;
    const coast=coastlineProfile(f,level.seed,{samples:144});
    const sides=[
      {normal:{x:1,z:0},tangent:{x:0,z:1},span:f.d,edge:{x:f.x+f.w/2,z:f.z}},
      {normal:{x:-1,z:0},tangent:{x:0,z:-1},span:f.d,edge:{x:f.x-f.w/2,z:f.z}},
      {normal:{x:0,z:1},tangent:{x:-1,z:0},span:f.w,edge:{x:f.x,z:f.z+f.d/2}},
      {normal:{x:0,z:-1},tangent:{x:1,z:0},span:f.w,edge:{x:f.x,z:f.z-f.d/2}},
    ];
    for(const side of sides){
      if(side.span<maxW+2.0)continue;
      for(const shift of [0,-.23,.23,-.40,.40]){
        const t=shift*side.span;
        if(Math.abs(t)+maxW/2+.5>side.span/2)continue;
        const center={
          x:side.edge.x+side.tangent.x*t+side.normal.x*.19,
          z:side.edge.z+side.tangent.z*t+side.normal.z*.19,
        };
        if(!safeAnchorage(level,res,coast,center,side.normal,side.tangent,maxW,maxD))continue;
        // Prefer other islands than the fishing gear, but never require one.
        // A remote island landmark can pass a screenshot test while remaining
        // unseen for almost the entire raid. Prioritize the START island first.
        const fromStart=level.start?Math.hypot(center.x-level.start.x,center.z-level.start.z):0;
        const startPriority=islandIndex===0?10:islandIndex===1?5:Math.max(0,3-islandIndex);
        const score=startPriority+r()*.3-fromStart*.006+
          (islandIndex!==excludeIsland?.12:0);
        candidates.push({islandIndex,center,ry:Math.atan2(side.normal.x,side.normal.z),
          normal:side.normal,score});
      }
    }
  }
  return candidates.sort((a,b)=>b.score-a.score||a.islandIndex-b.islandIndex);
}
export function planMilitaryRemnantsDressing(level,{quality='high',density=1}={}){
  const bounded=clamp(Number.isFinite(density)?density:1,0,1);
  // Keep approved Forest/Granite/Coastal Life and their mobile item budgets.
  const base=planCoastalLifeDressing(level,{quality,density:bounded*.84});
  const unchanged={regions:base.regions,items:base.items,landmarks:base.landmarks,
    militaryLandmarks:[],architecture:[]};
  if(!level?.archipelago||bounded<.5)return unchanged;
  const sites=militarySites(level,base.landmarks[0]?.islandIndex??-1);
  const selected=[],perIsland=new Map();
  // Discrete coastal-defence complexes rather than a continuous concrete rim.
  // Allow one main landmark plus one distinct outwork on an island.
  const limit=level.big?6:4;
  for(const site of sites){
    const placed=perIsland.get(site.islandIndex)??0;
    if(placed>=2)continue;
    if(selected.some(other=>Math.hypot(other.center.x-site.center.x,other.center.z-site.center.z)<6.0))continue;
    const fishing=base.landmarks[0];
    if(fishing?.islandIndex===site.islandIndex&&
      Math.hypot(fishing.center.x-site.center.x,fishing.center.z-site.center.z)<4.6)continue;
    const r=seededRandom(level.seed+':bungenas-form-v4:'+site.islandIndex+':'+
      site.center.x.toFixed(2)+':'+site.center.z.toFixed(2));
    const sameIsland=selected.find(other=>other.islandIndex===site.islandIndex);
    // First ruin needs a readable pillbox or portal. Companion sites use
    // distinct forms so neighboring remains do not become obvious duplicates.
    const variants=selected.length===0?[MILITARY_FORMS[0],MILITARY_FORMS[2]]:
      MILITARY_FORMS.filter(form=>form.id!==sameIsland?.scene);
    const form=variants[Math.floor(r()*variants.length)];
    selected.push({type:'military',scene:form.id,islandIndex:site.islandIndex,
      center:site.center,ry:site.ry,width:form.width,depth:form.depth,
      height:form.height,siteRole:sameIsland?'outwork':'landmark',visualOnly:true});
    perIsland.set(site.islandIndex,placed+1);
    if(selected.length>=limit)break;
  }
  // Remove obscuring tall dressing, but keep a natural forest/granite baseline.
  // The architecture itself adds grass, heather, moss and encroaching saplings.
  const cleared=base.items.filter(item=>item.profile==='coastal-life'||!selected.some(site=>
    Math.hypot(item.x-site.center.x,item.z-site.center.z)<4.7));
  return {regions:base.regions,items:cleared,
    landmarks:[...base.landmarks,...selected],militaryLandmarks:selected,
    architecture:selected};
}
